import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { format, resolveConfig } from "prettier";

const data = JSON.parse(readFileSync("docs/security-remediation.json", "utf8"));
const banner =
  "<!-- Generated by scripts/security-remediation-reports.mjs; edit docs/security-remediation.json. -->";
const escape = (value) =>
  String(value ?? "")
    .replaceAll("|", "\\|")
    .replaceAll("\n", " ");
const table = (headings, rows) =>
  [headings, headings.map(() => "---"), ...rows]
    .map((row) => `| ${row.map(escape).join(" | ")} |`)
    .join("\n");
const context = `Reviewed ${data.checkedAt}. Baseline \`${data.baselineCommit}\`; branch \`${data.branch}\`.
Source fingerprint: \`${data.sourceFingerprint}\`.

${data.scope}

**Release: NO-GO.** Local implementation, local verification and deployment are separate. No application deployment or provider purchase is authorized by these reports.`;
const limits = data.limits.map((line) => `- ${line}`).join("\n");
const commands = table(
  ["Check", "Status", "Evidence"],
  data.checks.map((c) => [c.name, c.status, c.detail]),
);
const findings = table(
  ["Finding", "Implementation", "Verification", "Deployed"],
  data.findings.map((f) => [f.id, f.implementation, f.verification, f.deployment]),
);
const files = {
  "QA_REPORT.md": `# Security repair phase QA\n\n${context}\n\n${commands}\n\n## Limits\n\n${limits}\n`,
  "QA_CHECKLIST.md": `# Security repair acceptance checklist\n\n${context}\n\n${data.checks.map((c) => `- [${c.status === "PASS" ? "x" : " "}] ${c.name}: ${c.status}. ${c.detail}`).join("\n")}\n\n## Outstanding independent gates\n\n${limits}\n`,
  "BUG_TRACKER.md": `# Security repair findings\n\n${context}\n\n${findings}\n\nRemaining scoped alerts and external verification are recorded without relabelling them as passes.\n\n${limits}\n`,
  "RELEASE_READINESS.md": `# Security repair release readiness\n\n${context}\n\n${commands}\n\n## Essential remaining gates\n\n${limits}\n\nMerging main deploys. These local records do not authorize a merge or deployment, certify OAuth/payment providers, or promote imported game data to current-patch verified.\n`,
  "PRODUCT_IMPROVEMENTS.md": `# Security and correctness improvements\n\n${context}\n\n${findings}\n\nThe repair preserves existing brand, source facts and manual-price distinctions. It does not claim full product, accessibility, game-patch or field-performance acceptance.\n\n${limits}\n`,
  "IMPLEMENTATION_STATUS.md": `# Security repair implementation status\n\n${context}\n\n${findings}\n\n## Verification\n\n${commands}\n\n${limits}\n`,
  "PROJECT_PLAN.md": `# Security repair project plan\n\n${context}\n\n${findings}\n\n## Remaining work\n\n${limits}\n\nKeep the original assessment and private reproduction bundle as historical evidence. Repeat affected formula, authorization, cache and migration tests after any follow-up change.\n`,
};
const options = await resolveConfig("QA_REPORT.md");
let stale = false;
for (const [path, markdown] of Object.entries(files)) {
  const content = await format(`${banner}\n\n${markdown}`, { ...options, parser: "markdown" });
  const old = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (process.argv.includes("--check")) {
    if (old !== content) {
      console.error(`${path}: stale`);
      stale = true;
    }
  } else {
    if (old !== null && !old.startsWith(banner))
      throw new Error(`Refusing to replace unowned report ${path}`);
    writeFileSync(path, content);
  }
}
if (stale) process.exitCode = 1;
else
  console.log(
    process.argv.includes("--check")
      ? "Seven security phase reports are current"
      : "Generated seven security phase reports",
  );
